// Last 7 days (Dubai time) from the sheet tabs.
const now = DateTime.now().setZone('Asia/Dubai');
const since = now.minus({ days: 7 });
function inWeek(t) {
  const d = DateTime.fromFormat(String(t || ''), 'yyyy-MM-dd HH:mm', { zone: 'Asia/Dubai' });
  return d.isValid && d >= since;
}
function rows(name) { return $(name).all().map(function (i) { return i.json || {}; }).filter(function (r) { return !r.error && Object.keys(r).length; }); }
const conv = rows('Read Conversations').filter(function (r) { return inWeek(r.time); });
const incoming = conv.filter(function (r) { return r.direction === 'in'; });
const patients = rows('Read Patients');
const cancels = rows('Read Cancellations').filter(function (r) { return inWeek(r.time); });
const unanswered = rows('Read Unanswered').filter(function (r) { return inWeek(r.time); });

const chats = new Set(incoming.map(function (r) { return String(r.phone); })).size;
const booked = patients.filter(function (r) { return ['booked', 'confirmed', 'completed'].indexOf(String(r.status).toLowerCase()) >= 0 && inWeek(r.last_message_at); }).length;
const handovers = conv.filter(function (r) { return /team member will|our team will|سيتواصل|هيتواصل|فريق/i.test(String(r.text)) && r.direction === 'out'; }).length;
const cancelAsked = cancels.filter(function (r) { return r.saved === 'asked'; }).length;
const cancelSaved = cancels.filter(function (r) { return r.saved === 'yes'; }).length;
const cancelled = cancels.filter(function (r) { return r.saved === 'no'; }).length;

// Most common topics from incoming messages (simple keyword buckets).
const TOPICS = { price: /price|cost|how much|بكام|سعر|كم/i, booking: /book|appointment|slot|موعد|ميعاد|احجز/i, cancel: /cancel|resched|الغ|إلغ|تأجيل/i, location: /where|location|parking|address|فين|وين|موقع|موقف/i, insurance: /insurance|daman|تأمين/i, pain: /pain|hurt|swell|وجع|ألم|الم|ورم/i, whitening: /whiten|تبييض/i, aligners: /align|braces|تقويم/i, hours: /open|hours|time|مواعيد|الساعة/i };
const counts = {};
incoming.forEach(function (r) { Object.keys(TOPICS).forEach(function (k) { if (TOPICS[k].test(String(r.text))) counts[k] = (counts[k] || 0) + 1; }); });
const top = Object.keys(counts).sort(function (a, b) { return counts[b] - counts[a]; }).slice(0, 5).map(function (k) { return k + ' (' + counts[k] + ')'; }).join(', ') || 'none';

// Up to 20 recent conversations for the AI review.
const byPhone = {};
conv.forEach(function (r) { const p = String(r.phone); (byPhone[p] = byPhone[p] || []).push((r.direction === 'in' ? 'Patient: ' : 'Noor: ') + String(r.text).slice(0, 300)); });
const sample = Object.keys(byPhone).slice(-20).map(function (p, i) { return 'Conversation ' + (i + 1) + ':\n' + byPhone[p].slice(-12).join('\n'); }).join('\n\n');

const week = since.toFormat('d LLL') + ' - ' + now.toFormat('d LLL yyyy');
const line = chats + (chats === 1 ? ' patient' : ' patients') + ' chatted, ' + incoming.length + ' messages, ' + booked + ' booked/confirmed, ' + cancelAsked + ' cancel requests (' + cancelSaved + ' saved, ' + cancelled + ' cancelled), ' + handovers + ' handovers to staff, ' + unanswered.length + ' unanswered questions. Top topics: ' + top + '.';
return [{ json: { week: week, line: line.replace(/\s+/g, ' ').slice(0, 900), sample: sample || 'No conversations this week.', unanswered: unanswered.map(function (u) { return u.question; }).join(' | ') } }];

