const raw = String(($input.first().json || {}).text || '');
const m = raw.match(/\[[\s\S]*\]/);
let list = [];
try { list = m ? JSON.parse(m[0]) : []; } catch (e) { list = []; }
const week = $('Build Weekly Stats').first().json.week;
const out = list.slice(0, 5).map(function (s) { return { json: { week: week, suggestion: String(s.suggestion || ''), example: String(s.example || ''), status: 'proposed' } }; });
return out.length ? out : [{ json: { week: week, suggestion: 'No suggestions this week', example: '', status: 'info' } }];
